public final class NonPokemonBatch102Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final List<String> IDS=List.of("xy5-5_en_025","xy5-5_en_026","xy5-5_en_027","xy5-5_en_028","xy5-5_en_029","xy5-5_en_030","xy5-5_en_031","xy5-5_en_032");
    static int fixtureSeed;
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static UUID other(UUID p){return p.equals(A)?B:A;}
    static CardInstance hand(ServerMatch m,UUID p,String id){return DynamicPassiveModifierTest.hand(m,p,id);}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static UUID bench(ServerMatch m,UUID p){return m.benchPokemonView(p).getFirst().pokemonId();}
    static void settle(ServerMatch m){NonPokemonBatch2Test.settle(m);}
    static void select(ServerMatch m,UUID p,List<CardInstance> cards){var q=m.effectCardPrompt(p);m.submitEffectCards(p,q.resolutionId(),q.step(),cards.stream().map(CardInstance::instanceId).toList());}
    static void discard(ServerMatch m,UUID p,CardInstance card){var h=PairedTrainerPlayTest.zone(m,p,"hand");check(h.remove(card),"Fixture discard source missing");PairedTrainerPlayTest.zone(m,p,"discard").add(card);}
    static ServerMatch game(String id){return game(id,false);}
    static ServerMatch game(String id,boolean entryAbility){
        var kinds=List.of("normal","normal","normal","normal","aqua","aqua","magma","magma","ae","me","water","water","fighting","fighting","special","trainer","trainer","other","fossil");
        var defs=new ArrayList<CardDefinition>();var profiles=new HashMap<String,PokemonProfile>();
        var attack=BundledCombatData.attack(JsonParser.parseString("{\"id\":\"hit\",\"nameZh\":\"hit\",\"energyCost\":{},\"baseDamage\":100,\"damageType\":\"COLORLESS\",\"effectSupport\":\"SUPPORTED\"}").getAsJsonObject(),EffectRegistry.standard());
        var trainer=NonPokemonBatch2Test.DATA.trainer(id).orElseThrow();
        for(String key:new LinkedHashSet<>(kinds)){
            boolean pokemon=Set.of("normal","aqua","magma","ae","me").contains(key),energy=Set.of("water","fighting","special").contains(key);
            String name=Set.of("aqua","ae").contains(key)?"Team Aqua's "+key:Set.of("magma","me").contains(key)?"Team Magma's "+key:key;
            defs.add(new CardDefinition(key,key,pokemon?CardCategory.POKEMON:energy?CardCategory.ENERGY:CardCategory.TRAINER,key.equals("trainer")?trainer.category():energy||pokemon?TrainerCategory.NONE:TrainerCategory.ITEM,"H",Set.of("international"),Set.of("normal","aqua","magma").contains(key),energy&&!key.equals("special"),60,Map.of(),EffectSupport.SUPPORTED,null));
            if(pokemon)profiles.put(key,new PokemonProfile(600,2,key.equals("ae")?"aqua":key.equals("me")?"magma":null,null,0,null,0,1,List.of(attack),entryAbility&&key.equals("normal")?List.of(AnyStageDeckPlacementTest.event("ON_ENTER_PLAY","HAND")):List.of(),EnergyType.COLORLESS,name,null));
        }
        var combat=new CombatCatalog(profiles,Map.of("water",EnergyType.WATER,"fighting",EnergyType.FIGHTING),Map.of("trainer",trainer,"other",NonPokemonBatch2Test.DATA.trainer("xy11_en_099").orElseThrow(),"fossil",NonPokemonBatch2Test.DATA.trainer("sm12_en_197").orElseThrow()),Map.of("special",EnergyProfile.fixed(EnergyType.WATER,2)));
        for(int seed=fixtureSeed;seed<fixtureSeed+1500;seed++){
            var decks=new ArrayList<List<CardInstance>>();for(UUID p:List.of(A,B)){var cards=new ArrayList<CardInstance>();for(int i=0;i<60;i++)cards.add(new CardInstance(new UUID(p.getLeastSignificantBits(),i+1),p,kinds.get(i%kinds.size())));decks.add(cards);}
            var m=new ServerMatch(A,B,decks.get(0),decks.get(1),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),combat,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);
            if(List.of(A,B).stream().anyMatch(p->m.privateView(p).hand().stream().filter(c->c.definitionId().equals("normal")).count()<2))continue;
            for(UUID p:List.of(A,B)){var normal=m.privateView(p).hand().stream().filter(c->c.definitionId().equals("normal")).toList();m.chooseOpeningActive(p,normal.getFirst().instanceId());m.placeOpeningBench(p,normal.get(1).instanceId());m.startAfterOpening(p);}OpeningTestSupport.complete(m,A,B,1);
            m.drawCardsByEffect(A,A,23);m.drawCardsByEffect(A,B,23);m.endTurn(A);m.endTurn(B);
            if(List.of(A,B).stream().allMatch(p->new LinkedHashSet<>(kinds).stream().allMatch(k->m.privateView(p).hand().stream().anyMatch(c->c.definitionId().equals(k)))&&List.of("aqua","magma","water","fighting").stream().allMatch(k->m.privateView(p).deck().stream().filter(c->c.definitionId().equals(k)).count()>=2))){fixtureSeed=seed;return m;}
        }throw new AssertionError("Team Trainer fixture unavailable");
    }
    static UUID add(ServerMatch m,UUID p,String key){var card=hand(m,p,key);m.playBasicPokemonToBench(p,card.instanceId());settle(m);return PokemonIdentityTestSupport.logical(m,p,card.instanceId());}
    static ServerMatch aiGame(String id){var m=game(id);if(id.equals(IDS.getFirst())){UUID host=add(m,A,"aqua");m.switchActiveByEffect(A,A,host);discard(m,A,hand(m,A,"water"));}if(id.equals("xy5-5_en_029")){discard(m,A,hand(m,A,"magma"));discard(m,A,hand(m,A,"me"));}return m;}
    public static void main(String[] args){grunts();balls();admins();aquaBase();magmaBase();magmaSources();order();authority();ai();schema();System.out.println("NonPokemonBatch102Test passed: eight Aqua/Magma Trainers, exact original cost bonus and short decks, one-per-kind shared reveal/typed Basic search, Active-only Basic attachment and named recovery, live both-player retreat, physical hand-to-Bench events/forced entry/Item Pokemon/order, atomic choices and all AI difficulties");}
    static void grunts(){for(String id:List.of("xy5-5_en_026","xy5-5_en_030"))for(UUID p:List.of(A,B))for(String chosen:List.of("aqua","magma","ae","me","trainer","water")){
        var m=game(id);if(p.equals(B))m.endTurn(A);var source=hand(m,p,"trainer");var cost=hand(m,p,chosen);if(cost.equals(source))cost=m.privateView(p).hand().stream().filter(c->c.definitionId().equals("trainer")&&!c.equals(source)).findFirst().orElseThrow();int before=m.privateView(p).hand().size(),deck=m.privateView(p).deck().size();m.playTrainer(p,source.instanceId(),null);check(m.privateView(p).deck().size()==deck,"Grunt drew before paying");select(m,p,List.of(cost));settle(m);boolean bonus=id.equals("xy5-5_en_026")?Set.of("aqua","ae").contains(chosen):Set.of("magma","me").contains(chosen);check(m.privateView(p).hand().size()==before-2+3+(bonus?1:0)&&m.privateView(p).discard().contains(cost),"Grunt wrong actual discard bonus: "+id+" "+chosen);
    }for(int n:List.of(0,1,3)){var m=game("xy5-5_en_026");m.discardTopDeckCardsByEffect(A,A,m.privateView(A).deck().size()-n);var source=hand(m,A,"trainer");check(m.canPlayTrainer(A,source.instanceId(),null)==(n>0),"Grunt empty-deck cost-only play");if(n==0)continue;int before=m.privateView(A).hand().size();m.playTrainer(A,source.instanceId(),null);select(m,A,List.of(hand(m,A,"aqua")));settle(m);check(m.privateView(A).hand().size()==before-2+n&&m.phase()==MatchPhase.TURN,"Grunt short deck draw");}
        var alone=game("xy5-5_en_030");var source=hand(alone,A,"trainer");var h=PairedTrainerPlayTest.zone(alone,A,"hand");var removed=h.stream().filter(c->!c.equals(source)).toList();h.removeAll(removed);PairedTrainerPlayTest.zone(alone,A,"discard").addAll(removed);check(!alone.canPlayTrainer(A,source.instanceId(),null),"Grunt paid with itself");
    }
    static void balls(){for(String id:List.of("xy5-5_en_027","xy5-5_en_031"))for(UUID p:List.of(A,B))for(int mask=0;mask<4;mask++){
        var m=game(id);if(p.equals(B))m.endTurn(A);String team=id.equals("xy5-5_en_027")?"aqua":"magma",energy=id.equals("xy5-5_en_027")?"water":"fighting";var deck=List.copyOf(m.privateView(p).deck());m.playTrainer(p,hand(m,p,"trainer").instanceId(),null);var q=m.effectCardPrompt(p);var legal=deck.stream().filter(c->Set.of(team,energy).contains(c.definitionId())).toList();check(new HashSet<>(q.candidates()).equals(new HashSet<>(legal)),"Great Ball admitted wrong stage/team/Energy");var chosen=new ArrayList<CardInstance>();if((mask&1)!=0)chosen.add(legal.stream().filter(c->c.definitionId().equals(team)).findFirst().orElseThrow());if((mask&2)!=0)chosen.add(legal.stream().filter(c->c.definitionId().equals(energy)).findFirst().orElseThrow());select(m,p,chosen);
        if(!chosen.isEmpty()){var reveal=m.effectCardReveal();check(reveal!=null&&reveal.cardIds().size()==chosen.size()&&m.privateView(p).deck().equals(deck),"Great Ball did not reveal together before moving");m.acknowledgeEffectReveal(other(p),reveal.id());}check(!m.hasPendingEffectChoice()&&m.privateView(p).hand().containsAll(chosen)&&m.privateView(p).deck().size()==deck.size()-chosen.size(),"Great Ball partial search failed");
    }}
    static void admins(){for(UUID p:List.of(A,B))for(boolean correct:List.of(false,true)){var m=game("xy5-5_en_025");if(p.equals(B))m.endTurn(A);UUID team=add(m,p,"aqua");if(correct)m.switchActiveByEffect(p,p,team);for(String id:List.of("water","fighting","special"))discard(m,p,hand(m,p,id));var source=hand(m,p,"trainer");check(m.canPlayTrainer(p,source.instanceId(),null)==correct,"Aqua Admin ignored Active team requirement");if(!correct)continue;m.playTrainer(p,source.instanceId(),null);var q=m.effectCardPrompt(p);check(q.candidates().stream().allMatch(c->Set.of("water","fighting").contains(c.definitionId()))&&q.candidates().size()==2,"Aqua Admin required Water or accepted Special Energy");var chosen=q.candidates().stream().filter(c->c.definitionId().equals("fighting")).findFirst().orElseThrow();select(m,p,List.of(chosen));settle(m);check(m.activePokemonView(p).attachedEnergyIds().equals(List.of(chosen.instanceId())),"Aqua Admin attached to wrong host");}
        for(int n:List.of(0,1,2,3)){var m=game("xy5-5_en_029");var team=m.privateView(A).hand().stream().filter(c->Set.of("magma","me").contains(c.definitionId())).limit(3).toList();check(team.size()==3,"Recovery fixture");team.forEach(c->discard(m,A,c));discard(m,A,hand(m,A,"aqua"));m.playTrainer(A,hand(m,A,"trainer").instanceId(),null);check(new HashSet<>(m.effectCardPrompt(A).candidates()).equals(new HashSet<>(team)),"Magma Admin missed evolutions or accepted other team");select(m,A,team.subList(0,n));settle(m);check(m.privateView(A).hand().containsAll(team.subList(0,n))&&m.privateView(A).discard().containsAll(team.subList(n,3)),"Magma Admin wrong up-to count");}
    }
    static void aquaBase(){for(UUID controller:List.of(A,B)){var m=game("xy5-5_en_028");if(controller.equals(B))m.endTurn(A);m.playTrainer(controller,hand(m,controller,"trainer").instanceId(),null);for(UUID p:List.of(controller,other(controller))){if(!m.currentPlayer().equals(p))m.endTurn(m.currentPlayer());check(m.activeRetreatCost(p)==3,"Aqua Base failed other team");UUID aqua=add(m,p,"aqua");m.switchActiveByEffect(p,p,aqua);check(m.activeRetreatCost(p)==2,"Aqua Base affected Team Aqua");m.evolveByEffect(p,aqua,hand(m,p,"ae").instanceId(),EvolutionPermission.CARD_EFFECT_ALL_TIMING);check(m.activeRetreatCost(p)==2,"Aqua Base lost team evolution exemption");}m.discardStadiumByEffect(m.currentPlayer());check(m.activeRetreatCost(A)==2&&m.activeRetreatCost(B)==2,"Aqua Base lingered");}}
    static void magmaBase(){for(UUID controller:List.of(A,B))for(UUID owner:List.of(A,B))for(String kind:List.of("normal","aqua","magma")){var m=game("xy5-5_en_032");if(controller.equals(B))m.endTurn(A);m.playTrainer(controller,hand(m,controller,"trainer").instanceId(),null);if(!owner.equals(controller))m.endTurn(controller);UUID added=add(m,owner,kind);check(m.benchPokemonView(owner).stream().filter(v->v.pokemonId().equals(added)).findFirst().orElseThrow().damage()==(kind.equals("magma")?0:20),"Magma Base team/owner filter failed");check(m.activePokemonView(owner).damage()==0&&m.benchPokemonView(owner).getFirst().damage()==0,"Magma Base hit preexisting Pokemon");}}
    static void magmaSources(){var m=game("xy5-5_en_032");m.playTrainer(A,hand(m,A,"trainer").instanceId(),null);var deck=m.privateView(A).deck().stream().filter(c->c.definitionId().equals("aqua")).findFirst().orElseThrow();m.putBasicPokemonFromOwnDeckToBenchByEffect(A,new ServerMatch.CardSelectionPolicy(1,1,CardCategory.POKEMON,null,true,Set.of()),List.of(deck.instanceId()));settle(m);check(m.benchPokemonView(A).getLast().damage()==0,"Magma Base hit deck entry");m.evolveByEffect(A,m.benchPokemonView(A).getLast().pokemonId(),hand(m,A,"ae").instanceId(),EvolutionPermission.CARD_EFFECT_ALL_TIMING);settle(m);check(m.benchPokemonView(A).getLast().damage()==0,"Magma Base hit hand evolution");var doll=hand(m,A,"fossil");m.playTrainer(A,doll.instanceId(),null);settle(m);check(m.benchPokemonView(A).getLast().topCardId().equals("fossil")&&m.benchPokemonView(A).getLast().damage()==20,"Magma Base omitted Item Pokemon");
        var forced=game("xy5-5_en_032");forced.playTrainer(A,hand(forced,A,"trainer").instanceId(),null);var wanted=hand(forced,B,"aqua");forced.playTrainer(A,hand(forced,A,"other").instanceId(),null);if(forced.effectCardReveal()!=null)forced.acknowledgeEffectReveal(A,forced.effectCardReveal().id());select(forced,A,List.of(wanted));settle(forced);check(forced.benchPokemonView(B).stream().anyMatch(v->v.topCardId().equals("aqua")&&v.damage()==20),"Magma Base omitted forced opponent hand entry");
    }
    static void order(){for(boolean stadiumFirst:List.of(false,true)){var m=game("xy5-5_en_032",true);m.playTrainer(A,hand(m,A,"trainer").instanceId(),null);int before=m.privateView(A).hand().size();var card=hand(m,A,"normal");m.playBasicPokemonToBench(A,card.instanceId());var q=m.triggerOrderPrompt();check(q!=null&&q.choosingPlayer().equals(A)&&q.entries().size()==2,"Entry did not offer simultaneous ordering");var selected=q.entries().stream().filter(e->stadiumFirst?e.nameZh().contains("秘密基地"):!e.nameZh().contains("秘密基地")).findFirst().orElseThrow();m.chooseTriggeredEffect(A,q.id(),selected.id());settle(m);check(m.privateView(A).hand().size()==before&&m.benchPokemonView(A).getLast().damage()==20,"Entry order lost draw or counters");}}
    static void authority(){for(String id:List.of("xy5-5_en_027","xy5-5_en_031")){var m=game(id);m.playTrainer(A,hand(m,A,"trainer").instanceId(),null);var q=m.effectCardPrompt(A);for(String kind:List.of(id.equals("xy5-5_en_027")?"aqua":"magma",id.equals("xy5-5_en_027")?"water":"fighting")){var pair=q.candidates().stream().filter(c->c.definitionId().equals(kind)).limit(2).toList();GeneratedRuleBatch44Test.assertRejectedAtomic(m,()->select(m,A,pair));}var first=q.candidates().getFirst();GeneratedRuleBatch44Test.assertRejectedAtomic(m,()->m.submitEffectCards(B,q.resolutionId(),q.step(),List.of(first.instanceId())));GeneratedRuleBatch44Test.assertRejectedAtomic(m,()->select(m,A,List.of(first,first)));select(m,A,List.of());GeneratedRuleBatch44Test.assertRejectedAtomic(m,()->m.submitEffectCards(A,q.resolutionId(),q.step(),List.of(first.instanceId())));}}
    static void ai(){for(String id:IDS)for(var d:AiDifficulty.values()){var m=aiGame(id);m.playTrainer(A,hand(m,A,"trainer").instanceId(),null);AiCardOperationTest.settle(MatchSession.multiplayer(m,A,B),d);if(id.equals("xy5-5_en_032")){m.playBasicPokemonToBench(A,hand(m,A,"normal").instanceId());AiCardOperationTest.settle(MatchSession.multiplayer(m,A,B),d);}check(!m.hasPendingEffectChoice()&&m.triggerOrderPrompt()==null&&m.phase()==MatchPhase.TURN,"AI stalled Team Trainer: "+id+" "+d);}}
    static void schema(){var e=NonPokemonBatch2Test.DATA.trainer("xy5-5_en_027").orElseThrow().effectProgram().triggers().getFirst().effects().getFirst();for(var kv:Map.of("amount","3","pokemon_name_or_basic_energy_type","FIGHTING","basic_pokemon_only","false","reveal","false").entrySet()){var a=new HashMap<>(e.arguments());a.put(kv.getKey(),kv.getValue());GeneratedRuleBatch8Test.reject(()->DistinctCardKindSelection.validate(new EffectDefinition(e.type(),e.target(),a,List.of(),List.of())));}GeneratedRuleBatch8Test.reject(()->PokemonChangeTriggerPolicy.parse(JsonParser.parseString("{\"trigger\":\"ON_ENTER_PLAY\",\"watch\":\"ANY_FIELD\",\"source\":\"DECK\",\"basicBenchEntryOnly\":true,\"optional\":false,\"usage\":\"NONE\"}").getAsJsonObject(),EffectTrigger.ON_ENTER_PLAY));}
}
